+/* QMux support {{{ */
+
+quic_info_data_t *
+quic_info_data_create_for_qmux(dissector_handle_t app_handle, dissector_handle_t app_datagram_handle)
+{
+    quic_info_data_t *conn = wmem_new0(wmem_file_scope(), quic_info_data_t);
+    conn->app_handle = app_handle;
+    conn->app_datagram_handle = app_datagram_handle;
+    conn->skip_decryption = true; /* No QUIC-layer crypto for QMux */
+    return conn;
+}
+
+int
+dissect_quic_frame_type_for_qmux(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree,
+                                 unsigned offset, quic_info_data_t *quic_info, bool from_server)
+{
+    /* Dummy packet info; packet_type != QUIC_LPT_0RTT so app_handle is used. */
+    quic_packet_info_t dummy_packet = { 0 };
+    dummy_packet.packet_type = QUIC_LPT_HANDSHAKE; /* anything != 0-RTT */
+
+    return dissect_quic_frame_type(tvb, pinfo, tree, offset, quic_info, &dummy_packet, from_server);
+}
